        yield return new object[] { "105: masks obfuscated form keys with opaque values through the default options path", "body: client%5Fse\u200Bcret=opaque-value-123&safe=1", "body: client%5Fse\u200Bcret=***&safe=1" };
        yield return new object[] { "106: masks obfuscated form keys with opaque values through the default options path", "GET https://example.test/cb?client_se+cret=opaque-value-123&safe=1", "GET https://example.test/cb?client_se+cret=***&safe=1" };
        yield return new object[] { "107: masks obfuscated form keys with opaque values through the default options path", "body: client_secre%74=opaque-value-123&safe=1", "body: client_secre%74=***&safe=1" };
        yield return new object[] { "108: masks obfuscated form keys with opaque values through the default options path", "body: client_se\u3164cret\u3164=opaque-value-123&safe=1", "body: client_se\u3164cret\u3164=***&safe=1" };
        yield return new object[] { "109: masks connection-string passwords through the default options path", "postgres://dbuser:opaquepw12345@db.example.test/openclaw", "postgres://dbuser:***@db.example.test/openclaw" };
        yield return new object[] { "110: masks quoted standalone values containing the other quote character", "password=\"it's-a-secret\" next", "password=\"***\" next" };
        yield return new object[] { "111: masks unterminated quoted standalone values", "token=\"opaque-abc123 rest", "token=*** rest" };
        yield return new object[] { "112: redacts raw secret values that contain an ellipsis", "password=abcdef\u20261234567890", "password=***" };
    }

